def _en_with(fn, ns):
    """run a tools/skyyench.py function with the table lists of `ns` swapped in (its functions read the module globals)"""
    def call(*a, **kw):
        keep = dict((n, getattr(_EN_LIVE, n)) for n in ("TABLE", "KEYS", "IDS", "RIDS", "BASE_LABEL"))
        try:
            for n in keep:
                setattr(_EN_LIVE, n, getattr(ns, n))
            return fn(*a, **kw)
        finally:
            for n, v in keep.items():
                setattr(_EN_LIVE, n, v)
    return call


