# ================= 0.2.19 STONE CONVERSIONS (Skyy 2026-10-15: "could you add a way to craft rubble from cobblestone and vise versa")
# Our own standalone recipe assets (Server/Item/Recipes/SkyyCollections/<id>.json); no vanilla / pack file overridden, no lang key.
# Derived here from Assets.zip + the SkyyBazaar SET pin's price table; the notes at the top say why each number is what it is.
import json as _sjson, ast as _sast
import deploy_set as _SDS
STONE_DIR = "Server/Item/Recipes/SkyyCollections/"
STONE_ID_FWD = "SkyyCollections_Stone_Cobble_To_Rubble_"      # + the stone key
STONE_ID_REV = "SkyyCollections_Stone_Rubble_To_Cobble_"
STONE_COB_TO_RUB = 1          # rubble per cobble = the vanilla Salvagebench ratio (Salvage_Rock_<Stone>_Cobble: 1 -> 1)
STONE_RUB_MIN = 2             # rubble per cobble the other way: 2, raised per stone until the Bazaar no-profit rule holds
STONE_SPREAD = 0.10           # SkyyBazaar's default spread: instant buy = base x 1.1, instant sell = base x 0.9
STONE_BENCH = [{"Type": "Crafting", "Id": "Fieldcraft", "Categories": ["Tools"]},                # pocket crafting (the Campfire's)
               {"Type": "Crafting", "Id": "Workbench", "Categories": ["Workbench_Survival"]}]  # Workbench, Survival tab (the Campfire's)
STONE_KEYS = ["Aqua", "Basalt", "Calcite", "Chalk", "Lime", "Magma_Cooled", "Marble", "Quartzite", "Sandstone",
              "Sandstone_Red", "Sandstone_White", "Shale", "Slate", "Stone", "Stone_Mossy", "Volcanic"]
STONE_PAIRS = []              # (stone key, cobble id, rubble id)
STONE_VANILLA = []            # vanilla recipes that already convert a pair: (recipe id, "fwd" / "rev", stone key, in qty, out qty)
with SA.assets() as _sz:
    _spath = {}
    for _n in _sz.namelist():
        if _n.startswith("Server/Item/Items/") and _n.endswith(".json"):
            _spath[os.path.basename(_n)[:-5]] = _n

    def _sjs(n):
        return _sjson.loads(_sz.read(n).decode("utf-8-sig"))
    for _i in sorted(_spath):
        _m = re.match(r"^Rock_([A-Za-z_]+?)_Cobble(_Mossy)?$", _i)
        if _m and ("Rubble_" + _m.group(1) + (_m.group(2) or "")) in _spath:
            STONE_PAIRS.append((_m.group(1) + (_m.group(2) or ""), _i, "Rubble_" + _m.group(1) + (_m.group(2) or "")))
    assert sorted(k for k, _c, _r in STONE_PAIRS) == sorted(STONE_KEYS + ["Dawnstone"]), "0.2.19: the cobble / rubble pairs moved: %s" % STONE_PAIRS
    # what players actually pick up: the small block AND its _Medium give exactly the small Rubble_<Stone> (break + F-pickup: Gathering
    # Soft / Harvest = an ItemId or a DropList); a rubble no block hands out (Dawnstone: its blocks drop Stone Rubble) gets no recipe
    _sdrop = dict((os.path.basename(n)[:-5], n) for n in _sz.namelist() if n.startswith("Server/Drops/") and n.endswith(".json"))

    def _sids(o):
        if isinstance(o, dict):
            return ([o["ItemId"]] if isinstance(o.get("ItemId"), str) else []) + [x for v in o.values() for x in _sids(v)]
        if isinstance(o, list):
            return [x for v in o for x in _sids(v)]
        return []

    def _sgives(i):
        _g = (_sjs(_spath[i]).get("BlockType") or {}).get("Gathering") or {}
        _out = set()
        for _t in ("Soft", "Harvest"):
            _e = _g.get(_t) or {}
            if _e.get("ItemId"):
                _out.add(_e["ItemId"])
            elif _e.get("DropList") in _sdrop:
                _out |= set(_sids(_sjs(_sdrop[_e["DropList"]])))
            else:
                _out.add(None)
        return _out
    STONE_SKIP = []
    for _p in list(STONE_PAIRS):
        _k, _c, _r = _p
        if _sgives(_r) != set([_r]) or (_r + "_Medium" in _spath and _sgives(_r + "_Medium") != set([_r])):
            STONE_SKIP.append("%s (its blocks give %s)" % (_k, ", ".join(sorted(str(x) for x in _sgives(_r)))))
            STONE_PAIRS.remove(_p)
    assert sorted(k for k, _c, _r in STONE_PAIRS) == sorted(STONE_KEYS) and len(STONE_SKIP) == 1 and STONE_SKIP[0].startswith("Dawnstone "), \
        "0.2.19: the picked-up rubble moved: kept %s, skipped %s" % ([k for k, _c, _r in STONE_PAIRS], STONE_SKIP)
    # the vanilla pocket category + the Workbench tab the recipes use
    assert "Server/Item/Category/Fieldcraft/Tools.json" in _sz.namelist(), "0.2.19: the pocket crafting category Fieldcraft/Tools moved"
    _wb = ((_sjs(_spath["Bench_WorkBench"]).get("BlockType") or {}).get("Bench") or {})
    assert _wb.get("Id") == "Workbench" and "Workbench_Survival" in [c.get("Id") for c in _wb.get("Categories") or []], "0.2.19: Workbench_Survival moved"
    _camp = (_sjs(_spath["Bench_Campfire"]).get("Recipe") or {}).get("BenchRequirement") or []
    assert sorted((b.get("Id"), tuple(b.get("Categories") or [])) for b in _camp) == sorted((b["Id"], tuple(b["Categories"])) for b in STONE_BENCH), \
        "0.2.19: the Campfire recipe's benches moved: %s" % _camp
    # vanilla recipes (item Recipe blocks + Server/Item/Recipes/**) that already convert a pair: forward ones must match our ratio,
    # a reverse one must not exist (both would need a new decision)
    _cob = dict((c, k) for k, c, r in STONE_PAIRS)
    _rub = dict((r, k) for k, c, r in STONE_PAIRS)
    _rids = set()
    for _n in _sz.namelist():
        if not (_n.startswith("Server/Item/") and _n.endswith(".json")):
            continue
        _st = _n.startswith("Server/Item/Recipes/")
        if not (_st or _n.startswith("Server/Item/Items/")):
            continue
        try:
            _d = _sjs(_n)
        except Exception:
            continue
        if not isinstance(_d, dict):
            continue
        _b = os.path.basename(_n)[:-5]
        if _st:
            _rid, _r0 = _b, _d
            _po = _d.get("PrimaryOutput") or {}
            _outs = [(_po.get("ItemId"), _po.get("Quantity", 1))]
        elif isinstance(_d.get("Recipe"), dict):
            _rid, _r0 = _b + "_Recipe_Generated_0", _d["Recipe"]
            _po = _r0.get("PrimaryOutput") or {}
            _outs = [(_po.get("ItemId"), _po.get("Quantity", 1))] if _po.get("ItemId") else [(_b, _r0.get("OutputQuantity") or 1)]
        else:
            continue
        _rids.add(_rid)
        _ins = [x for x in (_r0.get("Input") or []) if isinstance(x, dict)]
        for _o, _oq in _outs:
            if _o in _rub and any(x.get("ItemId") in _cob for x in _ins):
                assert len(_ins) == 1 and _cob[_ins[0]["ItemId"]] == _rub[_o], "0.2.19: an odd vanilla cobble -> rubble recipe %s" % _rid
                STONE_VANILLA.append((_rid, "fwd", _rub[_o], _ins[0].get("Quantity", 1), _oq))
            if _o in _cob and any(x.get("ItemId") in _rub or x.get("ResourceTypeId") == "Rubble" for x in _ins):
                STONE_VANILLA.append((_rid, "rev", _cob[_o], 0, _oq))
    _rev = [v for v in STONE_VANILLA if v[1] == "rev"]
    assert not _rev, "0.2.19: vanilla now makes cobble from rubble (%s) - match its ratio (tools/collections_0_2_19_patch.py 3)" % _rev
    _bad = [v for v in STONE_VANILLA if v[4] * 1.0 / v[3] != STONE_COB_TO_RUB]
    assert not _bad, "0.2.19: a vanilla cobble -> rubble recipe has another ratio: %s" % _bad
    assert len(STONE_VANILLA) == 13 and all(v[0].startswith("Salvage_Rock_") for v in STONE_VANILLA), "0.2.19: the vanilla salvage list moved: %s" % STONE_VANILLA
# the SkyyBazaar SET pin's base prices (its PRODUCTS table, read from the build script without running it): None = AUTO (processed)
_sbz = os.path.join(HERE, "..", "SkyyBazaar", "build_skyybazaar_%s.py" % dict(_SDS.SET)["SkyyBazaar"])
STONE_PRICE = {}
for _node in _sast.parse(open(_sbz, encoding="utf8").read()).body:
    if isinstance(_node, _sast.Assign) and [getattr(t, "id", None) for t in _node.targets] == ["PRODUCTS"]:
        _lst = _node.value.left if isinstance(_node.value, _sast.BinOp) else _node.value
        if not isinstance(_lst, (_sast.List, _sast.Tuple)):
            continue          # 0.2.20: SkyyBazaar 0.1.14+ re-assigns PRODUCTS (tier prices, the x4.5 scale) - only the literal table is read
        for _e in _lst.elts:
            if isinstance(_e, _sast.Tuple) and isinstance(_e.elts[0], _sast.Constant):
                STONE_PRICE[_e.elts[0].value] = _e.elts[1].value if isinstance(_e.elts[1], _sast.Constant) else None
assert STONE_PRICE.get("Rock_Stone_Cobble") == 1 and STONE_PRICE.get("Rubble_Stone") == 0.5, "0.2.19: the Bazaar table moved (%s)" % _sbz


def _snum(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool) and v > 0


def _srecipe(inp, qin, out, qout):
    return {"Input": [{"ItemId": inp, "Quantity": qin}], "PrimaryOutput": {"ItemId": out, "Quantity": qout},
            "Output": [{"ItemId": out, "Quantity": qout}], "BenchRequirement": [dict(b, Categories=list(b["Categories"])) for b in STONE_BENCH],
            "TimeSeconds": 0, "KnowledgeRequired": False}


STONE_RCP = []                # (recipe id, input id, input qty, output id, output qty)
STONE_ONEWAY = []             # stone keys without the rubble -> cobble recipe (not two fixed-price Bazaar products)
_S_BUY, _S_SELL = 1 + STONE_SPREAD, 1 - STONE_SPREAD
for _k, _c, _r in STONE_PAIRS:
    _pc, _pr = STONE_PRICE.get(_c, "none"), STONE_PRICE.get(_r, "none")
    # forward: 1 cobble -> STONE_COB_TO_RUB rubble never pays (a sellable rubble needs a fixed-price cobble)
    assert not _snum(_pr) or (_snum(_pc) and STONE_COB_TO_RUB * _pr * _S_SELL < _pc * _S_BUY), "0.2.19: %s cobble -> rubble pays (%s, %s)" % (_k, _pc, _pr)
    STONE_RCP.append((STONE_ID_FWD + _k, _c, 1, _r, STONE_COB_TO_RUB))
    if not (_snum(_pc) and _snum(_pr)):
        STONE_ONEWAY.append(_k)
        continue
    _n = max(STONE_RUB_MIN, STONE_COB_TO_RUB)          # never fewer rubble than one cobble gives (a round trip never gains)
    while not (_pc * _S_SELL < _n * _pr * _S_BUY):
        _n += 1
    STONE_RCP.append((STONE_ID_REV + _k, _r, _n, _c, 1))
assert STONE_ONEWAY == [], "0.2.19: one-way stones moved: %s" % STONE_ONEWAY
assert sorted((r[0], r[2]) for r in STONE_RCP if r[0].startswith(STONE_ID_REV) and r[2] != 2) == [(STONE_ID_REV + "Magma_Cooled", 3)], "0.2.19: ratios moved"
assert len(STONE_RCP) == 32 and len(set(r[0] for r in STONE_RCP)) == 32
assert not set(r[0] for r in STONE_RCP) & _rids, "0.2.19: a stone recipe id clashes with a vanilla recipe"
STONE_FILES = dict((STONE_DIR + _rid + ".json", _sjson.dumps(_srecipe(_i, _qi, _o, _qo), indent=2) + "\n") for _rid, _i, _qi, _o, _qo in STONE_RCP)
print("0.2.19 stone conversions: %d recipes (%d cobble -> %d rubble; rubble -> cobble %s; one-way %s); vanilla already: %d Salvagebench "
      "1 -> 1 (%s); left out %s; pocket Fieldcraft/Tools + Workbench/Workbench_Survival; Bazaar table %s" % (
          len(STONE_RCP), sum(1 for r in STONE_RCP if r[0].startswith(STONE_ID_FWD)), STONE_COB_TO_RUB,
          ", ".join("%s %d" % (r[0][len(STONE_ID_REV):], r[2]) for r in STONE_RCP if r[0].startswith(STONE_ID_REV) and r[2] != 2) + ", others 2",
          ", ".join(STONE_ONEWAY) or "none", len(STONE_VANILLA), ", ".join(v[2] for v in STONE_VANILLA), "; ".join(STONE_SKIP), os.path.basename(_sbz)))

# ================= registry defaults (every id checked against Assets.zip) =================
