# ---- 0.2.20 (critic fix B1): every normal-tool RECIPE reward (SkyyGear 0.3.13 removes those recipes) -> that collection's Enchanted item
# x (2 x tier, cap 64); no Enchanted item -> coins:<tier.coins of that tier>; a tier that already gives an item keeps only that item.
# TL_ROWS = the live lines (key, 0.2.19 value, 0.2.20 value) for CollToolMig; TL_COMMENT = the commented proposals (old line, new line)
TL_RE = re.compile(r"^recipe:(Tool_(Pickaxe|Hatchet|Hoe|Sickle)_[A-Za-z_]+|Tool_Watering_Can[A-Za-z_]*)_Recipe_Generated_0$")


def tl_norm(tok):
    """SkyyGear GearLL.normKind's rule on a recipe token: a normal pickaxe / hatchet / hoe / sickle / watering can (no multitool / Harvester)"""
    return bool(TL_RE.match(tok)) and not re.search(r"(?i)multi|harvester", tok)


TL_ENCH = {}
for _t in EN.TABLE_20:          # 0.2.21: frozen to the 20 rows of 0.2.20 (a C1 row - Mithril - would move CollToolMig's comment table)
    TL_ENCH.setdefault(_t[3], EN.PREFIX + _t[0])          # collection id -> its (first) Enchanted item


def tl_new(key, toks):
    _coll, _tier = key.rsplit(".", 1)
    _keep = [x for x in toks if not tl_norm(x)]
    if any(x.startswith("item:") for x in _keep):
        return _keep                                       # one item a tier: the Unique Sigil stays, the dead recipe token goes
    _e = TL_ENCH.get(_coll)
    _n = "item:%s:%d" % (_e, min(64, 2 * int(_tier))) if _e else "coins:%d" % TIER_COINS[min(int(_tier), len(TIER_COINS)) - 1]
    return [_n] + _keep


TL_ROWS, TL_COMMENT = [], []
for _i, _l in enumerate(RW):
    _com = _l.startswith("#")
