assert not [l for l in RW if any(tl_norm(x) for x in l.lstrip("#").split("=", 1)[-1].split(","))], "0.2.20 B1: a tool recipe reward is left"
# the catch-up table: the tiers whose 0.2.20 value gives a NEW item (not the Sigil tiers)
