_sdir = os.path.join(HERE, "..", "SkyySacks")
_sacks = sorted([f for f in os.listdir(_sdir) if re.match(r"^build_skyysacks_\d+(\.\d+)*\.py$", f)], key=_ver) if os.path.isdir(_sdir) else []
