# ================= 0.2.24 GIFT SIZING (round coll24; tools/skyyench.py GIFT_SHARE / gift_size) + the retired Life Essence item =================
# RW (above) = the 0.2.21 default file = CollRw21Mig's NEWV = CollRw24Mig's OLD values. Every Enchanted gift token (item:Skyy_Ench_* - the 0.2.20
# ones too - and the retired id, which becomes the vanilla Greater Essence) gets n = gift_size(step of that tier, its 0.2.21 n): at most
# GIFT_SHARE % of the items the tier asks for (step = its amount minus the tier before), never more than before; 0 = the token goes (a line
# with nothing left goes). A VANILLA_ENCH collection's Enchanted-recipe tier (no recipe any more) gets the grammar's gift as well.
RW021 = list(RW)
C24_CURVE = dict((r[0], CURVES[r[2]]) for r in REG)


def _c24_step(cid, t):
    a = C24_CURVE[cid]
    return a[t - 1] - (a[t - 2] if t > 1 else 0)


_C24_GIFT = set(EN_OLD.IDS) | set(_v[0] for _v in EN.VANILLA_ENCH.values())
RW24_V, C24_SIZED, C24_GONE = {}, 0, 0
for _k, _v in RW21_V.items():
    _cid, _t = _k.rsplit(".", 1)
    _t = int(_t)
    _out = []
    for _x in _v.split(","):
        _p = _x.split(":")
        if _x.startswith("item:") and len(_p) == 3 and _p[1] in _C24_GIFT:
            _iid = EN.RETIRED_TO.get(_p[1], _p[1])
            _n = EN.gift_size(_c24_step(_cid, _t), int(_p[2]))
            C24_SIZED += 1
            if _n > 0:
                _out.append("item:%s:%d" % (_iid, _n))
            else:          # Skyy 2026-10-16 "Give base items there": the collection's base item, the same 10 % value cap
                C24_GONE += 1
                _out.append("item:%s:%d" % (_REGI[_cid][5][0], EN.base_gift_size(_c24_step(_cid, _t))))
            continue
        _out.append(_x)
    if _out:
        RW24_V[_k] = ",".join(_out)
for _cid, (_vid, _vcat) in EN.VANILLA_ENCH.items():
    _e = C1_E[_cid][1]
    _k = "%s.%d" % (_cid, _e)
    _n = EN.gift_size(_c24_step(_cid, _e), min(64, 2 * _e))
    if _k not in RW21_V:
        RW24_V[_k] = "item:%s:%d" % (_vid, _n) if _n > 0 else "item:%s:%d" % (_REGI[_cid][5][0], EN.base_gift_size(_c24_step(_cid, _e)))
assert not any(EN_RET[0] in _v for _v in RW24_V.values()), "0.2.24: no reward names the retired item"
for _k, _v in RW24_V.items():          # never more than before; at most GIFT_SHARE % of the step
    _cid, _t = _k.rsplit(".", 1)
    for _x in _v.split(","):
        _p = _x.split(":")
        if _x.startswith("item:") and _p[1] in _C24_GIFT:
            assert int(_p[2]) * EN.RATIO * 100 <= EN.GIFT_SHARE * _c24_step(_cid, int(_t)), (_k, _v)
        elif _x.startswith("item:") and _p[1] == _REGI[_cid][5][0]:          # a base-item gift: <= 10 % of the step, 1 - 64
            assert 1 <= int(_p[2]) <= 64 and int(_p[2]) * 100 <= max(100, EN.GIFT_SHARE * _c24_step(_cid, int(_t))), (_k, _v)
assert all(any(_x.startswith("item:") for _x in RW24_V.get(_k, "").split(",")) for _k, _v in RW21_V.items() if "item:" in _v), "0.2.24: every tier with a 0.2.21 gift still gives an item"
