for _cid in ("Cobblestone", "Iron", "Mithril", "Wheat", "OakLog", "LifeEssence"):
    print("  %-12s 0.2.21 %s" % (_cid, " | ".join("%d:%s" % (t, RW21_V.get("%s.%d" % (_cid, t), "-").split(",")[0].replace("item:", "")) for t in range(1, len(C24_CURVE[_cid]) + 1))))
    print("  %-12s 0.2.24 %s" % ("", " | ".join("%d:%s" % (t, RW24_V.get("%s.%d" % (_cid, t), "-").split(",")[0].replace("item:", "")) for t in range(1, len(C24_CURVE[_cid]) + 1))))
# ================= 0.2.25 TIER REWARDS of the five new collections (round ores01): the C1 grammar + the 0.2.24 gift sizing, no tier-ups =================
# every tier except the Enchanted-recipe tier e: the own Enchanted item, n = gift_size(step, min(64, 2 x tier)); under one Enchanted item the base
# item (base_gift_size(step)). = the partner metals' rows without their pickaxe / armor tier-ups (SkyyGear has no Lead ... Titanium tier yet).
RW25_V = {}
for (cid, cat, curve, name, icon, items, flags, frm) in REG:
    if cid not in NEW25:
        continue
    _row = [_t for _t in EN.TABLE if _t[3] == cid]
    assert len(_row) == 1 and not [k for k in RW24_V if k.rsplit(".", 1)[0].lower() == cid.lower()], cid
    _E, _e = EN.PREFIX + _row[0][0], _row[0][4]
    for _t in range(1, len(CURVES[curve]) + 1):
        if _t == _e:
            continue
        _st = _c24_step(cid, _t)
        _n = EN.gift_size(_st, min(64, 2 * _t))
        RW25_V["%s.%d" % (cid, _t)] = "item:%s:%d" % (_E, _n) if _n > 0 else "item:%s:%d" % (items[0], EN.base_gift_size(_st))
C25_K = sorted(RW25_V, key=lambda k: (NEW25.index(k.rsplit(".", 1)[0]), int(k.rsplit(".", 1)[1])))
C25_ROWS = [(k, "", RW25_V[k]) for k in C25_K]
assert len(C25_ROWS) == (8 - 1) * 2 + (7 - 1) * 2 + (9 - 1), len(C25_ROWS)
assert CURVES["S"][6] == 5000 and [r for r in REG if r[0] == "Charcoal"][0][2] == "S", "0.2.25: Charcoal tier VII = 5,000 (the Eternal Flame gate)"
RW_MARK7 = "# ores01: Lead, Chromium, Slag, Titanium and Charcoal collection rewards (0.2.25)"
assert "=" not in RW_MARK7 and all(32 <= ord(_c) < 127 for _c in RW_MARK7)
RW_SECTION7 = "# Collection rewards added by SkyyCollections 0.2.25 (round ores01)"
assert RW[len(_hdr) + 1] == RW_MARK6
RW = RW[:len(_hdr) + 2] + [RW_MARK7] + RW[len(_hdr) + 2:] + [RW_SECTION7] + ["%s=%s" % (k, RW25_V[k]) for k in C25_K]
assert len(set(l.split("=", 1)[0].lower() for l in RW if l and not l.startswith("#"))) == len(RW24_V) + len(RW25_V)
print("0.2.25 new collection rewards: %d lines (%s)" % (len(C25_ROWS), "; ".join("%s %s" % (_c, " | ".join(
    "%d:%s" % (_t, RW25_V.get("%s.%d" % (_c, _t), "Enchanted recipe").replace("item:", "")) for _t in range(1, len(C24_CURVE[_c]) + 1))) for _c in NEW25)))
# ================= 0.2.24 ETERNAL SEEDS (Skyy 2026-10-16 "lets lock the eternal seeds with the collection. give them at like collection level 3 or 4")
# every visible Farming crop collection whose first item is Plant_Crop_<Crop>_Item and whose vanilla Plant_Seeds_<Crop>_Eternal has an item
# recipe (the engine id <item>_Recipe_Generated_0): that recipe unlocks at the crop's tier eternal.tier (default 4, 1-10), made
# KnowledgeRequired at run time and managed in the known-recipe set; the Bazaar asks coll:fn:eternal before selling one.
ETER_DEF = 4
ETER = []          # (seed item id, recipe id, collection id, display name)
with zipfile.ZipFile(ASSETS) as _ez:
    _eip = dict((os.path.basename(n)[:-5], n) for n in _ez.namelist() if n.startswith("Server/Item/Items/") and n.endswith(".json"))
    for (_cid, _cat, _cv, _nm, _ic, _its, _fl, _frm) in REG:
        _m = re.match(r"^Plant_Crop_([A-Za-z]+)_Item$", _its[0]) if _its else None
        if _cat != "Farming" or "hidden" in _fl or not _m:
            continue
        _sid = "Plant_Seeds_%s_Eternal" % _m.group(1)
        if _sid not in _eip:
            continue
        _rj = __import__("json").loads(_ez.read(_eip[_sid]).decode("utf-8-sig")).get("Recipe") or {}
        assert _rj.get("Input") and not _rj.get("KnowledgeRequired") and any(b.get("Id") == "Farmingbench" for b in _rj.get("BenchRequirement", [])), (_sid, _rj)
        ETER.append((_sid, _sid + "_Recipe_Generated_0", _cid, LANG.get(_sid, _sid)))
assert len(ETER) == 14 and len(set(e[2] for e in ETER)) == 14, ("0.2.24: the 14 crops with an Eternal seed bag", [e[0] for e in ETER])
assert all(1 <= ETER_DEF <= len(C24_CURVE[e[2]]) for e in ETER)
print("0.2.24 Eternal seeds: %d recipes locked to crop collection tier %d by default (eternal.tier): %s" % (len(ETER), ETER_DEF, ", ".join(e[2] for e in ETER)))
