F(reg, "public static volatile int RLIVEN = -1;")
M(reg, r"""
public static boolean loaded(String rid) {
  if (rid == null) return false;
  try {
    com.hypixel.hytale.assetstore.map.DefaultAssetMap am = @CRR@.getAssetMap();
    if (am == null) return true;
    java.util.Map m = am.getAssetMap();
    if (m == null || m.isEmpty()) return true;
    int n = m.size();
    if (n != RLIVEN) { RLIVE.clear(); RLIVEN = n; }
    Object b = RLIVE.get(rid);
    if (b == null) {
      b = am.getAsset(rid) != null ? Boolean.TRUE : Boolean.FALSE;
      RLIVE.put(rid, b);
    }
    return ((Boolean) b).booleanValue();
  } catch (Throwable t) { return true; }
}""")
