M(reg, r"""
public static String[] liveOnly(String[] rs) {
  if (rs == null || rs.length == 0) return rs;
  int n = 0;
  for (int i = 0; i < rs.length; i++) if (!loaded(rs[i])) n++;
  if (n == 0) return rs;
  String[] out = new String[rs.length - n];
  int k = 0;
  for (int i = 0; i < rs.length; i++) {
    if (!loaded(rs[i])) continue;
    if (k < out.length) out[k] = rs[i];
    k++;
  }
  if (k != out.length) return rs;   // the store changed between the two passes: show all this once (the next call re-checks)
  return out;
}""")
