M(ckj, r"""
public void run() {
  String k = this.key;
  try {
    @PKG@.CollStore.KEYQ.remove(k);
    @PKG@.CollStore.KEYSAVES.incrementAndGet();
    if (@PKG@.CollStore.DIRTY.remove(k) == null) return;
    if (!@PKG@.CollStore.save(k)) @PKG@.CollStore.DIRTY.put(k, Boolean.TRUE);
  } catch (Throwable t) { @PKG@.CollStore.DIRTY.put(k, Boolean.TRUE); @PKG@.CollUtil.warn("counts save failed (kept dirty, retried in 10 s): " + t); }
}""")
M(sto, r"""
public static void saveKeySoon(String key) {
  if (key == null) return;
  java.util.concurrent.ExecutorService ex = WRITER;
  if (ex != null) {
    if (KEYQ.putIfAbsent(key, Boolean.TRUE) != null) return;
    try { ex.execute(new @PKG@.CollKeySaveJob(key)); return; }
    catch (Throwable t) { KEYQ.remove(key); }
  }
  if (DIRTY.remove(key) != null && !save(key)) DIRTY.put(key, Boolean.TRUE);
}""")
