# world thread, active profile only. {coins paid, xp paid, 1 = something is still owed}. synchronized: a queued retry on the old world
# thread can overlap a credit on the new one after a world switch - the paid markers are read and advanced under one monitor
# (SkyyCoins / SkyySkills never call back into this mod, so holding it across their functions cannot deadlock)
M(rew, r"""
public static synchronized long[] settle(@PKG@.CollData d, @PKG@.RegData R, int c, java.util.UUID u, String key) {
  long[] res = new long[3];
  if (d == null || R == null || R.hidden[c]) return res;
  if (!key.equals(@PKG@.CollUtil.pkey(u))) { res[2] = 1L; return res; }
  int ct = @PKG@.CollStore.countTier(d, R, c);
  String id = R.id[c];
  int pc = (int) @PKG@.CollStore.meta(d, "_paid." + id);
  for (int t = pc + 1; t <= ct; t++) {
    long n = @PKG@.CollReg.coinsAt(R, c, t);
    if (n > 0L && !coinsAdd(u, n)) { res[2] = 1L; break; }
    res[0] += n;
    @PKG@.CollStore.setMeta(d, key, "_paid." + id, (long) t);
  }
  int px = (int) @PKG@.CollStore.meta(d, "_paidxp." + id);
  for (int t = px + 1; t <= ct; t++) {
    java.util.ArrayList xs = @PKG@.CollReg.xpAt(R, c, t);
    boolean ok = true;
    for (int i = 0; i < xs.size(); i++) {
      Object[] a = (Object[]) xs.get(i);
      long amt = ((Long) a[1]).longValue();
      if (xpAdd(u, (String) a[0], amt, "coll:" + id + ":" + t, key)) { res[1] += amt; continue; }
      if (i == 0) { ok = false; break; }
      @PKG@.CollUtil.warn("extra XP reward " + a[0] + " " + amt + " for " + id + " " + t + " was refused and is skipped (the tier's first grant was paid)");
    }
    if (!ok) { res[2] = 1L; break; }
    @PKG@.CollStore.setMeta(d, key, "_paidxp." + id, (long) t);
  }
  // 0.2.20 B1 catch-up: the 0.2.20 item tiers BELOW the paid marker as it was at this profile's first 0.2.20 settle (stamp _cub020 =
  // it + 1), each once (own marker _cu020.<Id>, saved before the item); the normal loop below never goes under _paiditem
  if (cuHas(id)) {
    if (@PKG@.CollStore.meta(d, "_cub020." + id) <= 0L) @PKG@.CollStore.setMeta(d, key, "_cub020." + id, @PKG@.CollStore.meta(d, "_paiditem." + id) + 1L);
    int cb = cuBase(d, R, c);
    int cu = (int) @PKG@.CollStore.meta(d, "_cu020." + id);
    for (int t = cu + 1; t <= cb && t <= ct; t++) {
      if (!cuTier(R, c, t)) continue;
      int g = giveTierM(d, R, c, t, u, key, cu, "_cu020." + id);
      if (g != 1) { res[2] = 1L; break; }
      cu = t;
    }
  }
  // 0.2.21 C1 catch-up: the gift tiers the 0.2.21 default added BELOW the paid marker as it was at this profile's first 0.2.21 settle
  if (cuHas21(id)) {          // never skipped: the stamp must be taken before the normal loop below moves _paiditem
    if (@PKG@.CollStore.meta(d, "_cub021." + id) <= 0L) @PKG@.CollStore.setMeta(d, key, "_cub021." + id, @PKG@.CollStore.meta(d, "_paiditem." + id) + 1L);
    int cb2 = cuBase21(d, R, c);
    int cu2 = (int) @PKG@.CollStore.meta(d, "_cu021." + id);
    for (int t = cu2 + 1; t <= cb2 && t <= ct; t++) {
      if (!cuTier21(R, c, t)) continue;
      int g = giveTierM(d, R, c, t, u, key, cu2, "_cu021." + id);
      if (g != 1) { res[2] = 1L; break; }
      cu2 = t;
    }
  }
  // 0.2.13: the item rewards (own marker _paiditem.<Id>; only tiers that HAVE an item move it; the marker is saved before each item)
  int pi = (int) @PKG@.CollStore.meta(d, "_paiditem." + id);
  for (int t = pi + 1; t <= ct; t++) {
    if (@PKG@.CollReg.itemAt(R, c, t) == null) continue;
    int g = giveTier(d, R, c, t, u, key, pi);
    if (g != 1) { res[2] = 1L; break; }
    pi = t;
  }
  // 0.2.21 C1 rank gifts (Skyy "show, announce, and give a few enchanted items"): every rebirth rank reached above _paidrank.<Id>, once each
  if (ct >= @PKG@.CollReg.maxTier(R, c) && @PKG@.CollRebirth.rankOn(R, c)) {   // 0.2.24: a small first rank may give nothing, a later one something
    int rk = @PKG@.CollRebirth.ranks(R, c, @PKG@.CollStore.sum(d, R, c), key);
    int pr = (int) @PKG@.CollStore.meta(d, "_paidrank." + id);
    for (int k = pr + 1; k <= rk; k++) {
      int g = giveRank(d, R, c, k, u, key, pr);
      if (g != 1) { res[2] = 1L; break; }
      pr = k;
    }
  }
  if (res[0] > 0L || res[1] > 0L) @PKG@.CollStore.saveKeySoon(key);   // 0.2.10 fixer 2: the paid markers on disk now, not in <= 10 s
  return res;
}""")
M(rew, r"""
public static void settleAll(@PR@ pr, java.util.UUID u, String key) {
  @PKG@.RegData R = @PKG@.CollReg.D;
  @PKG@.CollData d = @PKG@.CollStore.dataK(key);
  if (R == null || d == null) return;
  long coins = 0L; long xp = 0L;
  for (int c = 0; c < R.n; c++) {
    long[] r = settle(d, R, c, u, key);
    coins += r[0];
    xp += r[1];
  }
  mark(key, d, R);
  if ((coins > 0L || xp > 0L) && pr != null && pr.isValid() && @PKG@.CollUtil.notifyOn(u, "rewards.late")) {
    pr.sendMessage(@MSG@.raw("[Collections] Paid for earlier collection tiers: " + (coins > 0L ? "+" + @PKG@.CollUtil.fmt(coins) + " coins" : "") + (coins > 0L && xp > 0L ? ", " : "") + (xp > 0L ? "+" + @PKG@.CollUtil.fmt(xp) + " skill XP" : "")).color("#ffc800"));
  }
}""")

# ================= 0.2.24 CollRetire: the retired Skyy_Ench_LifeEssence -> Greater Essence of Life, 1:1 IN THE SAME SLOT (round coll24) =================
# World thread only. Every stack of a RET_ID item in the player's storage / backpack / hotbar (CollRewards.secsOf - the gift sections) is swapped
# for new ItemStack(RET_TO, same quantity) with ONE compare-and-swap (replaceItemStackInSlot(slot, the exact stack read, the new stack)), then
# the slot is read back. Nothing is added or removed anywhere else, so every state a crash / relog / engine rollback can leave is either the old
# stack or the new one (never both, never none); the next scan converts what is left. Journal (retired-items.log): CONVERT-BEGIN before the
# write, CONVERT / CONVERT-UNDONE / CONVERT-CHECK after it. _retired.<id> in the profile's counts file = the total converted on that profile.
F(ret, "public static final java.util.concurrent.ConcurrentHashMap SEEN = new java.util.concurrent.ConcurrentHashMap();")   # players scanned once since join
F(ret, "public static final java.util.concurrent.ConcurrentHashMap VOIDASK = new java.util.concurrent.ConcurrentHashMap();")   # the Void asked once
F(ret, "public static final java.util.concurrent.atomic.AtomicLong DONE = new java.util.concurrent.atomic.AtomicLong();")
F(ret, "public static volatile long WARNAT;")
M(ret, r"""
public static void log(String line) {
  try { @PKG@.CollIO.append(@PKG@.CollReg.BASE.resolve("retired-items.log"), new java.util.Date() + "\t" + line + "\n"); } catch (Throwable t) { }
}""")
M(ret, r"""
public static void warnOnce(String m) {
  long now = System.currentTimeMillis();
  if (now - WARNAT > 60000L) { WARNAT = now; @PKG@.CollUtil.warn(m); }
}""")
# the Void (SkyySacks): asked once per player per start - 0.8.13 - 0.8.15 never homed the item, so a non-zero count is only reported
M(ret, r"""
public static void askVoid(java.util.UUID u) {
  if (u == null || VOIDASK.putIfAbsent(u, Boolean.TRUE) != null) return;
  try {
    Object f = @PKG@.CollUtil.bridge().get("sacks:fn:count");
    if (!(f instanceof java.util.function.Function)) return;
    for (int i = 0; i < @PKG@.CollEnch.RET_ID.length; i++) {
      Object r = ((java.util.function.Function) f).apply(new Object[] { u, @PKG@.CollEnch.RET_ID[i] });
      if (r instanceof Number && ((Number) r).longValue() > 0L) {
        @PKG@.CollUtil.warn("the Void of " + u + " holds " + r + " " + @PKG@.CollEnch.RET_ID[i] + " (SkyySacks never stored it before) - left there; take it out to have it converted");
        log("VOID\t" + u + "\t" + @PKG@.CollEnch.RET_ID[i] + " x" + r + " (not touched)");
      }
    }
  } catch (Throwable t) { }
}""")
# the sections the conversion looks at: the gift sections (storage, backpack, hotbar) + utility + armor (critic: those slots too; never
# used for gifts). The harness seam (CollRewards.SECS) = its sections only.
M(ret, r"""
public static @ICON@[] retSecs(java.util.UUID u) {
  @ICON@[] a = @PKG@.CollRewards.secsOf(u);
  if (a == null || @PKG@.CollRewards.SECS != null) return a;
  try {
    @PR@ pr = @UNI@.get().getPlayer(u);
    @REF@ r = pr == null ? null : pr.getReference();
    if (r == null || !r.isValid()) return a;
    @PLA@ p = (@PLA@) r.getStore().getComponent(r, @PLA@.getComponentType());
    @INVT@ inv = p == null ? null : p.getInventory();
    if (inv == null) return a;
    @ICON@[] b = new @ICON@[a.length + 2];
    for (int i = 0; i < a.length; i++) b[i] = a[i];
    b[a.length] = inv.getUtility();
    b[a.length + 1] = inv.getArmor();
    return b;
  } catch (Throwable t) { return a; }
}""")
# one player's scan: the number of items converted (>= 0), -1 = not now (offline, no inventory, SkyyProfiles holds it, the new item not loaded)
M(ret, r"""
public static long convert(java.util.UUID u) {
  if (u == null) return -1L;
  if (@PKG@.CollRewards.profileHold(u)) return -1L;
  @ICON@[] secs = retSecs(u);
  if (secs == null) return -1L;
  String key = @PKG@.CollUtil.pkey(u);
  long done = 0L;
  boolean stop = false;
  for (int k = 0; k < secs.length && !stop; k++) {
    @ICON@ c = secs[k];
    if (c == null) continue;
    boolean dup = false;
    for (int j = 0; j < k; j++) if (secs[j] == c) dup = true;
    if (dup) continue;
    for (int i = 0; i < c.getCapacity() && !stop; i++) {
      @IS@ x = c.getItemStack((short) i);
      if (x == null || x.isEmpty()) continue;
      int r = @PKG@.CollEnch.retIdx(x.getItemId());
      if (r < 0) continue;
      String to = @PKG@.CollEnch.RET_TO[r];
      if (!@PKG@.CollRewards.itemLoaded(to)) { warnOnce("cannot convert " + x.getItemId() + ": " + to + " is not loaded on this server (retried later)"); stop = true; continue; }
      int q = x.getQuantity();
      String where = k + "#" + i;
      log("CONVERT-BEGIN\t" + key + "\t" + u + "\t" + where + "\t" + x.getItemId() + " x" + q + " -> " + to + " x" + q);
      Object tx = null;
      try { tx = c.replaceItemStackInSlot((short) i, x, new @IS@(to, q)); } catch (Throwable t) { tx = null; }
      @IS@ y = c.getItemStack((short) i);
      if (y != null && !y.isEmpty() && to.equals(y.getItemId()) && y.getQuantity() == q) {
        done = done + (long) q;
        log("CONVERT\t" + key + "\t" + u + "\t" + where + "\t" + x.getItemId() + " x" + q + " -> " + to + " x" + q);
      } else if (y != null && !y.isEmpty() && x.getItemId().equals(y.getItemId()) && y.getQuantity() == q) {
        log("CONVERT-UNDONE\t" + key + "\t" + u + "\t" + where + "\t the slot refused the swap - still " + x.getItemId() + " x" + q + " (the next scan tries again)");
      } else {
        log("CONVERT-CHECK\t" + key + "\t" + u + "\t" + where + "\t the slot changed during the swap: now " + (y == null || y.isEmpty() ? "empty" : y.getItemId() + " x" + y.getQuantity()));
        warnOnce("Life Essence conversion: a slot changed during the swap (" + key + " " + where + ") - see retired-items.log");
      }
    }
  }
  if (done > 0L) {
    DONE.addAndGet(done);
    try {
      @PKG@.CollData d = @PKG@.CollStore.dataK(key);
      if (d != null) { @PKG@.CollStore.setMeta(d, key, "_retired." + @PKG@.CollEnch.RET_ID[0], @PKG@.CollStore.meta(d, "_retired." + @PKG@.CollEnch.RET_ID[0]) + done); @PKG@.CollStore.saveKeySoon(key); }
    } catch (Throwable t) { }
    try {
      @PR@ pr = @UNI@.get().getPlayer(u);
      if (pr != null && pr.isValid()) pr.sendMessage(@MSG@.raw("[Collections] Enchanted Essence of Life is retired: your " + @PKG@.CollUtil.fmt(done) + " became " + @PKG@.CollUtil.fmt(done) + " Greater Essence of Life (the same thing, the vanilla item).").color("#ffc800"));
    } catch (Throwable t) { }
  }
  return stop ? -1L : done;          // critic: the slots already swapped are booked even when a later one had to stop (-1 = scan again)
}""")
