M(rett, r"""
public void run() {
  try {
    @PR@ pr = @UNI@.get().getPlayer(this.u);
    if (pr == null || !pr.isValid() || this.world == null || !this.world.equals(pr.getWorldUuid())) return;   // moved world: the next tick queues it there
    long n = @PKG@.CollRetire.convert(this.u);
    if (n >= 0L) @PKG@.CollRetire.SEEN.put(this.u, Boolean.TRUE);
    @PKG@.CollRetire.askVoid(this.u);
  } catch (Throwable t) { @PKG@.CollRetire.warnOnce("Life Essence conversion failed (retried later): " + t); }
}""")
# every online player: a scan task on their world thread (the 1 s saver calls it every 15 s, and for a player not scanned since joining)
M(ret, r"""
public static void scanOnline(boolean all) {
  try {
    java.util.HashSet on = new java.util.HashSet();
    java.util.Iterator it = @UNI@.get().getPlayers().iterator();
    while (it.hasNext()) {
      @PR@ pr = (@PR@) it.next();
      if (pr == null || !pr.isValid()) continue;
      java.util.UUID u = pr.getUuid();
      on.add(u);
      if (!all && SEEN.containsKey(u)) continue;
      java.util.UUID wu = pr.getWorldUuid();
      @WLD@ w = wu == null ? null : @UNI@.get().getWorld(wu);
      if (w != null) w.execute(new @PKG@.CollRetireTask(u, wu));
    }
    SEEN.keySet().retainAll(on);
    VOIDASK.keySet().retainAll(on);
  } catch (Throwable t) { }
}""")
# ================= 0.2.11 the Enchanted recipe knowledge (spec F5): want = which of the Enchanted recipes (19; 20 since 0.2.20) this player's ACTIVE profile has
# unlocked (a "0" / "1" string, all "0" while ench.on is false); only a CHANGED want queues ONE CollKnowTask on the player's world thread
# (KPEND), which sets exactly the managed entries (ID.length) of the known-recipe set (PlayerConfigData; saved per player by the engine) and sends
# ONE UpdateKnownRecipes when something differs. KSIG = the want last applied. Retried every 30 s for a player whose want is not applied.
M(ench, r"""
public static String wantSig(java.util.Set ids) {
  char[] c = new char[MID.length];
  boolean on = ON;
  for (int k = 0; k < MID.length; k++) c[k] = ((on || k >= ID.length) && ids != null && ids.contains(MRID[k])) ? '1' : '0';   // 0.2.21: + the armor pieces
  return new String(c);
}""")
# the new known set: null = every managed entry already matches w; else known with each managed entry set to w (no other entry touched)
M(ench, r"""
public static java.util.HashSet next(java.util.Set known, String w) {
  if (w == null || w.length() != MID.length) return null;   // 0.2.21: the managed entries = Enchanted + the 16 first-set armor pieces
  boolean diff = false;
  for (int k = 0; k < MID.length && !diff; k++) {
    boolean has = known != null && known.contains(MID[k]);
    if (has != (w.charAt(k) == '1')) diff = true;
  }
  if (!diff) return null;
  java.util.HashSet ns = known == null ? new java.util.HashSet() : new java.util.HashSet(known);
  for (int k = 0; k < MID.length; k++) {
    if (w.charAt(k) == '1') ns.add(MID[k]); else ns.remove(MID[k]);
  }
  return ns;
}""")
M(ench, r"""
public static void warnOnce(String m) {
  long now = System.currentTimeMillis();
  if (now - WARNAT > 60000L) { WARNAT = now; @PKG@.CollUtil.warn(m); }
}""")
# the 19 managed entries of one known-recipe set set to w (true = changed; nothing else in the set is touched)
M(ench, r"""
public static boolean syncData(@PCD@ d, String w) {
  java.util.HashSet ns = next(d.getKnownRecipes(), w);
  if (ns == null) return false;
  d.setKnownRecipes(ns);
  return true;
}""")
# world thread: 1 = sent, 0 = nothing to do (already right), -1 = the player / component is not there (retried later)
M(ench, r"""
public static int apply(java.util.UUID u) {
  String w = (String) KWANT.get(u);
  if (w == null) return 0;
  @PR@ pr = @UNI@.get().getPlayer(u);
  if (pr == null || !pr.isValid()) return -1;
  @REF@ r = pr.getReference();
  if (r == null || !r.isValid()) return -1;
  @ST@ st = r.getStore();
  if (st == null) return -1;
  @PLA@ p = (@PLA@) st.getComponent(r, @PLA@.getComponentType());
  if (p == null) return -1;
  @PCD@ d = p.getPlayerConfigData();
  if (d == null) return -1;
  boolean ch = syncData(d, w);
  if (ch) { @CRP@.sendKnownRecipes(r, st); SENDS.incrementAndGet(); }
  KSIG.put(u, w);
  return ch ? 1 : 0;
}""")
