M(ench, r"""
public static void schedule(java.util.UUID u) {
  if (u == null) return;
  long now = System.currentTimeMillis();
  Object pend = KPEND.get(u);
  if (pend instanceof Long && now - ((Long) pend).longValue() < 10000L) return;   // one queued task per player (a lost one expires in 10 s)
  KPEND.put(u, Long.valueOf(now));
  try {
    @PR@ pr = @UNI@.get().getPlayer(u);
    if (pr == null || !pr.isValid()) { KPEND.remove(u); return; }
    java.util.UUID wu = pr.getWorldUuid();
    @WLD@ w = wu == null ? null : @UNI@.get().getWorld(wu);
    if (w == null) { KPEND.remove(u); return; }
    w.execute(new @PKG@.CollKnowTask(u, wu));
  } catch (Throwable t) { KPEND.remove(u); warnOnce("Enchanted recipe sync could not be queued (retried in 30 s): " + t); }
}""")
M(ktsk, r"""
public void run() {
  int res = -1;
  boolean moved = false;
  try {
    @PR@ pr = @UNI@.get().getPlayer(this.u);
    if (pr != null && pr.isValid() && this.world != null && !this.world.equals(pr.getWorldUuid())) moved = true;
    else {
      @PKG@.CollEnch.RUNS.incrementAndGet();
      res = @PKG@.CollEnch.apply(this.u);
    }
  } catch (Throwable t) { @PKG@.CollEnch.warnOnce("Enchanted recipe sync failed (retried in 30 s): " + t); }
  @PKG@.CollEnch.KPEND.remove(this.u);
  if (moved) { @PKG@.CollEnch.schedule(this.u); return; }
  Object w = @PKG@.CollEnch.KWANT.get(this.u);
  if (res >= 0 && w != null && !w.equals(@PKG@.CollEnch.KSIG.get(this.u))) @PKG@.CollEnch.schedule(this.u);
}""")
