M(c1, r"""
public static long points(@PKG@.CollData d, @PKG@.RegData R, String skill) {
  if (d == null || R == null || skill == null || !@PKG@.CollEnch.TP_ON) return 0L;
  Object[] kw = @PKG@.CollEnch.TP_KW;
  Object[] ow = @PKG@.CollEnch.TP_OW;
  if (kw == null || ow == null) return 0L;
  int si = skIdx(skill);
  java.util.HashSet keys = @PKG@.CollEnch.TP_KEYS;
  long n = 0L;
  for (int c = 0; c < R.n; c++) {
    if (R.hidden[c]) continue;
    String sk = skillOf(R, c);
    if (sk == null || !sk.equalsIgnoreCase(skill.trim())) continue;
    int ct = @PKG@.CollStore.countTier(d, R, c);
    if (ct <= 0) continue;
    long[] w = (long[]) (keys.contains(R.id[c].toLowerCase()) ? kw[si] : ow[si]);
    for (int t = 1; t <= ct; t++) n += weight(w, t);
  }
  long cap = @PKG@.CollEnch.TP_CAP;
  if (cap > 0L && n > cap) n = cap;
  return n;
}""")
