# coll:fn:tierup {key | UUID | null, "pickaxe:Thorium"} -> "<1 unlocked | 0>|<CollId>|<Name>|<tier>|<threshold>|<count>" for the LOWEST tier of a
# visible collection listing that tier-up (ties: registry order); null = no collection gates it (SkyyGear: open), a bad argument or an error
M(c1, r"""
public static Object tierup(Object arg) {
  try {
    if (!(arg instanceof Object[])) return null;
    Object[] a = (Object[]) arg;
    if (a.length < 2 || !(a[1] instanceof String)) return null;
    String want = ((String) a[1]).trim();
    int k = want.indexOf(':');
    if (k <= 0) return null;
    want = want.substring(0, k).trim().toLowerCase() + ":" + want.substring(k + 1).trim();
    @PKG@.RegData R = @PKG@.CollReg.D;
    if (R == null) return null;
    int bc = -1; int bt = 0;
    for (int c = 0; c < R.n; c++) {
      if (R.hidden[c]) continue;
      int mx = @PKG@.CollReg.maxTier(R, c);
      int lim = bt > 0 && bt - 1 < mx ? bt - 1 : mx;
      boolean hit = false;
      for (int t = 1; t <= lim && !hit; t++) {
        String[] tu = @PKG@.CollReg.tierupsAt(R, c, t);
        for (int i = 0; i < tu.length && !hit; i++) if (want.equalsIgnoreCase(tu[i])) { bc = c; bt = t; hit = true; }
      }
    }
    if (bc < 0) return null;
    String key = keyOf(a[0]);
    long n = 0L;
    if (key != null) {
      @PKG@.CollData d = @PKG@.CollStore.dataK(key);
      if (d != null) n = @PKG@.CollStore.sum(d, R, bc);
    }
    long th = @PKG@.CollReg.threshold(R, bc, bt);
    return (n >= th ? "1" : "0") + "|" + R.id[bc] + "|" + R.name[bc] + "|" + bt + "|" + th + "|" + n;
  } catch (Throwable t) { return null; }
}""")
# ================= CollUnlocks: coll:recipes + summary keys, per profile (the 0.1.5 publish / epoch chain) =================
M(unl, r"""
public static java.util.TreeSet compute0(@PKG@.CollData d) {
  java.util.TreeSet out = new java.util.TreeSet();
  @PKG@.RegData R = @PKG@.CollReg.D;
  if (d == null || R == null) return out;
  try {
    if (!@PKG@.CollReg.VALIDATED && @PKG@.CollMigrate.ready()) @PKG@.CollReg.validate();
    int bagMax = @PKG@.CollReg.BYP_BAGMAX;
    for (int c = 0; c < R.n; c++) {
      if (R.hidden[c]) continue;
      int ct = @PKG@.CollStore.countTier(d, R, c);
      int eff = @PKG@.CollStore.effTier(d, R, c);
      for (int t = 1; t <= eff; t++) {
        String[] rs = @PKG@.CollReg.recipesAt(c, t);
        for (int i = 0; i < rs.length; i++) {
          if (t > ct && @PKG@.CollUtil.bagRank(rs[i]) > bagMax) continue;
          out.add(rs[i]);
        }
      }
    }
    long km = @PKG@.CollStore.meta(d, @PKG@.CollCobMig.KEEP_META);   // 0.2.8: Mining bags unlocked through Iron before the move
    if (km > 0L) {
      for (int j = 0; j < @PKG@.CollCobMig.KEEP_RID.length; j++) if ((km & (1L << j)) != 0L) out.add(@PKG@.CollCobMig.KEEP_RID[j]);
    }
    if (!@PKG@.CollReg.AUTO) return out;
    java.util.Iterator rit = @CRR@.getAssetMap().getAssetMap().values().iterator();
    while (rit.hasNext()) {
      @CRR@ r = (@CRR@) rit.next();
      if (r == null || @PKG@.CollReg.excluded(r)) continue;
      @MQ@[] in = r.getInput();
      if (in == null || in.length == 0) continue;
      boolean anyTier = false; boolean blocked = false;
      for (int i = 0; i < in.length; i++) {
        if (in[i] == null || in[i].getItemId() == null) continue;
        Object ci = R.itemColl.get(in[i].getItemId());
        if (!(ci instanceof Integer)) continue;
        int c = ((Integer) ci).intValue();
        long s = @PKG@.CollStore.sum(d, R, c);
        if (s <= 0L) continue;
        if (s >= @PKG@.CollReg.threshold(R, c, 1)) anyTier = true; else blocked = true;
      }
      if (anyTier && !blocked) { String rid = r.getId(); if (@PKG@.CollUtil.autoOk(rid)) out.add(rid); }   // 0.2.11: never a Lantern / Enchanted recipe
    }
  } catch (Throwable t) { @PKG@.CollUtil.warn("unlock compute failed: " + t); }
  return out;
}""")
