# the output item id of a recipe id (the id minus "_Recipe_Generated_<n>", as CollUtil.prettyRecipe / CollCraft.words read it)
M(ctier, r"""
public static String itemOf(String rid) {
  if (rid == null) return null;
  String id = rid.trim();
  int g = id.indexOf("_Recipe_Generated_");
  return g > 0 ? id.substring(0, g) : id;
}""")
M(ctier, r"""
public static int metalTier(String id) {
  if (id == null) return 0;
  String[] w = id.split("_");
  for (int i = 0; i < w.length; i++) for (int j = 0; j < METAL_W.length; j++) if (w[i].equals(METAL_W[j])) return METAL_T[j];
  return 0;
}""")
M(ctier, r"""
public static int suffixTier(String id) {
  if (id == null) return 0;
  int u = id.lastIndexOf("_T");
  if (u >= 0 && u + 2 < id.length() && id.length() - u <= 5) {
    for (int i = u + 2; i < id.length(); i++) if (!Character.isDigit(id.charAt(i))) return 0;
    return Integer.parseInt(id.substring(u + 2));
  }
  return 0;
}""")
M(ctier, r"""
public static int ladderTier(String id) {
  if (id == null) return 0;
  Object o = ttMap().get(id);
  if (o != null) return ((Integer) o).intValue();
  return metalTier(id);
}""")
M(ctier, r"""
public static int tierKey(String id) {
  if (id == null) return 0;
  if (id.startsWith("Skyy_Acc") && id.endsWith("_Omni")) return 99;
  int st = suffixTier(id);
  if (st > 0) return st;
  String[] w = new String[] { "_Common", "_Uncommon", "_Rare", "_Epic", "_Legendary", "_Mythic" };
  for (int i = 0; i < w.length; i++) if (id.endsWith(w[i])) return i + 1;
  return ladderTier(id);
}""")
M(ctier, r"""
public static String tierText(String id) {
  if (id == null) return "";
  int st = suffixTier(id);
  if (st > 0) return "T" + st;
  int t = ladderTier(id);
  return t >= 1 && t <= LADDER_N ? "T" + t : "";
}""")
# tier, then name (lower case), then the id: < 0 = a before b. Rows: Object[] { rid, name, tag, Integer tierKey, String sortName, ... }
M(ctier, r"""
public static int cmp(Object[] a, Object[] b) {
  int ta = ((Integer) a[3]).intValue();
  int tb = ((Integer) b[3]).intValue();
  if (ta != tb) return ta < tb ? -1 : 1;
  return ((String) a[4]).compareTo((String) b[4]);
}""")

