COLL_RP_HS = SUI.grow_row_sizes(COLL_RP_IH, COLL_TR_H)                     # 0.2.23 (rule 7): [32, 46, 64] - a short recipe list grows
assert COLL_TR_REW == 560 and COLL_RP_NAME >= 200 and COLL_TT_W + COLL_RP_GAP + COLL_RP_W == COLL_IW, (COLL_TR_REW, COLL_RP_NAME)
