def coll_det_table():
    """The tier table: the column heads #SkyyCTHead (vanilla section labels over the cells) and the scrolling list #SkyyCTiers on the
    vanilla list well (TopScrolling + the vanilla scrollbar: a custom curve may have up to 20 tiers; 10 rows show at once). Every
    click rebuilds the page, so the scroll position goes back to the top (0.2.3's fixed rows ran off the page there instead).
    The heads are the kit's "section" labels: HorizontalAlignment: Start, a value no deployed page has used yet (probe base4
    shows it; UNVERIFIED in the build docstring).
    0.2.22: the row #SkyyCDMain holds the tier table (#SkyyCDLeft, COLL_TT_W) and, next to it, the recipe list (#SkyyCDRight: heads
    #SkyyCPHead over the scrolling well #SkyyCRecs, the same height) - recipes shown inside each collection."""
    ap = SUI.Appends()
    hh = 30 + COLL_TLIST_H
    ap.add("SkyyColl", SUI.group("SkyyCDMain", "Left", w=COLL_IW, h=hh))
    ap.add("SkyyCDMain", SUI.group("SkyyCDLeft", "Top", w=COLL_TT_W, h=hh))
    ap.add("SkyyCDLeft", COLL_TR_SPEC.heads("SkyyCTHead", outside=SUI.WELL_LIST_PAD))
    ap.add("SkyyCDLeft", SUI.scroll_list("SkyyCTiers", w=COLL_TT_W, h=COLL_TLIST_H, well=True))
    ap.add("SkyyCDMain", SUI.group("SkyyCDRight", "Top", w=COLL_RP_W, h=hh, anchor={"left": COLL_RP_GAP}))
    ap.add("SkyyCDRight", COLL_RP_SPEC.heads("SkyyCPHead", outside=SUI.WELL_LIST_PAD))
    ap.add("SkyyCDRight", SUI.scroll_list("SkyyCRecs", w=COLL_RP_W, h=COLL_TLIST_H, well=True))
    return ap


def coll_det_rec(i=None, go=False, nc=None, sc=None, tc=None, rh=COLL_TR_H):
    """0.2.22: one row #SkyyCPr<i> of the recipe list (the tier rows' look: the list row panel, one 32 px line): the tier tag #SkyyCPr<i>G
    (gold; grey when locked), the name #SkyyCPr<i>N (row name colour; grey when locked) and either the small Secondary CRAFT button
    #SkyyCPr<i>Go (bound cpk<i>, not locking: CollPage.bindFree) or the state word #SkyyCPr<i>S ("Tier III" grey / "Known" green).
    The cells are runtime texts (fit=False: CollCraft.fitPx cuts the name in the Java)."""
    i = _J(i, "i", "0")
    nc, sc, tc = _J(nc, "nc", SUI.COLOR["rowName"]), _J(sc, "sc", SUI.COLOR["disabled"]), _J(tc, "tc", SUI.COLOR["gold"])
    w = COLL_RP_SPEC.widths
    r = "SkyyCPr" + i
    cells = [SUI.label(r + "G", "", "bold", w=w[0], h=rh, col=tc, fit=False),        # 0.2.23: rh = the grow tier's row height
             SUI.label(r + "N", "", "default", w=w[1], h=rh, col=nc, fit=False)]
    if go:
        cells.append(SUI.button(r + "Go", "Craft", "secondary", "small", w=COLL_GO_W, h=COLL_TR_H,
                                anchor=dict({"left": COLL_GO_GAP}, **({"top": (rh - COLL_TR_H) // 2} if rh > COLL_TR_H else {}))))
    else:
        cells.append(SUI.label(r + "S", "", "bold", w=w[2], h=rh, col=sc, fit=False))
    row = SUI.panel(r, "row", h=rh, layout="Left", pad={"left": COLL_RP_SPEC.pad_left}, anchor={"bottom": SUI.ROW_GAP})
    return SUI.Appends([("SkyyCRecs", coll_inside(row, cells))])


