# 0.2.22: the recipes collection c unlocks at any tier (CollReg.recipesAt: loaded only, no bag while sacks:v2), each once (its lowest tier),
# sorted tier, then name (CollTier.cmp): Object[] { rid, name ("NEW  " first while that tier's NEW marker is up), tag "T2" / "",
# Integer tier key, String sort name, Boolean unlocked (in coll:recipes = un), Integer the collection tier that unlocks it }
M(page, r"""
public static java.util.ArrayList recipeRows(@PKG@.CollData d, @PKG@.RegData R, int c, int ct, java.util.TreeSet un) {
  java.util.ArrayList out = new java.util.ArrayList();
  if (R == null || c < 0 || c >= R.n) return out;
  java.util.HashSet seen = new java.util.HashSet();
  int mx = @PKG@.CollReg.maxTier(R, c);
  for (int t = 1; t <= mx; t++) {
    String[] rs = @PKG@.CollReg.recipesAt(c, t);
    for (int i = 0; i < rs.length; i++) {
      String rid = rs[i];
      if (rid == null || !seen.add(rid)) continue;
      String item = @PKG@.CollTier.itemOf(rid);
      String pn = @PKG@.CollUtil.prettyRecipe(rid);
      boolean ok = un != null && un.contains(rid);
      String nm = ok && t <= ct && d != null && @PKG@.CollNew.isNew(d, R, c, t) ? "NEW  " + pn : pn;
      Object[] e = new Object[] { rid, nm, @PKG@.CollTier.tierText(item), Integer.valueOf(@PKG@.CollTier.tierKey(item)), @PKG@.CollTier.sortName(item, pn, rid), Boolean.valueOf(ok), Integer.valueOf(t) };
      int at = out.size();
      for (int k = 0; k < out.size(); k++) {
        if (@PKG@.CollTier.cmp(e, (Object[]) out.get(k)) < 0) { at = k; break; }
      }
      out.add(at, e);
    }
  }
  return out;
}""")
