M(ckit, r"""
public static String idList(String value, String extra, String what) {
  String[] p = @PKG@.CollUtil.csv(value);
  if (p.length > 50) return "At most 50 " + what + "s.";
  for (int i = 0; i < p.length; i++) {
    String s = p[i];
    for (int k = 0; k < s.length(); k++) {
      char c = s.charAt(k);
      if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || extra.indexOf(c) >= 0)) return "Not a " + what + ": " + s + " (comma separated list).";
    }
  }
  return null;
}""")
M(ckit, r"""
public static String checkBenches(String key, String value) {
  return idList(value, "_-", "bench id");
}""")
M(ckit, r"""
public static String checkSources(String key, String value) {
  return idList(value, "_-:.", "source id");
}""")
# how the mod keys a rewards line: lower-case collection id + "." + the tier as a number (Wheat.03 = wheat.3)
M(ckit, r"""
public static String rewardKey(String k) {
  int dot = k.lastIndexOf('.');
  if (dot <= 0) return k.trim().toLowerCase();
  try { return k.substring(0, dot).trim().toLowerCase() + "." + Integer.parseInt(k.substring(dot + 1).trim()); } catch (Throwable t) { return k.trim().toLowerCase(); }
}""")
# { lines whose key is exactly e, lines the mod reads as the same entry } in rewards.properties on disk (the mod's line rules)
M(ckit, r"""
public static int[] rewardLines(String e) {
  int[] n = new int[2];
  try {
    java.nio.file.Path f = @PKG@.CollReg.BASE.resolve("rewards.properties");
    if (!java.nio.file.Files.exists(f, new java.nio.file.LinkOption[0])) return n;
    java.util.List lines = @PKG@.CollIO.readLines(f);
    String want = rewardKey(e);
    for (int i = 0; i < lines.size(); i++) {
      String ln = String.valueOf(lines.get(i)).trim();
      if (ln.length() == 0 || ln.startsWith("#")) continue;
      int eq = ln.indexOf('=');
      if (eq <= 0) continue;
      String k = ln.substring(0, eq).trim();
      if (k.equals(e)) n[0] = n[0] + 1;
      if (rewardKey(k).equals(want)) n[1] = n[1] + 1;
    }
  } catch (Throwable t) { }
  return n;
}""")
M(ckit, r"""
public static String rewardToken(String s) {
  if (s.startsWith("recipe:")) {
    String rid = s.substring(7).trim();
    if (rid.length() == 0) return "recipe: needs a recipe id, like recipe:Tool_Hoe_Copper_Recipe_Generated_0.";
    if (@PKG@.CollUtil.isLantern(rid)) return "Lantern recipes unlock at the Lantern recipes rows (Tree Sap tiers), not here.";
    if (!@PKG@.CollMigrate.ready()) return "?Recipes are not loaded yet (server still starting), so " + rid + " cannot be checked. Save it unchecked?";
    @CRR@ rr = null;
    try { rr = (@CRR@) @CRR@.getAssetMap().getAsset(rid); } catch (Throwable t) { }
    if (rr == null) return "Unknown recipe id: " + rid + " (recipe ids end in _Recipe_Generated_0).";
    if (@PKG@.CollReg.excluded(rr)) return rid + " is made at a bench on the Rules list Benches never unlocked - it would never unlock.";
    return null;
  }
  if (s.startsWith("coins:")) {
    try { if (Long.parseLong(s.substring(6).trim()) >= 0L) return null; } catch (Throwable t) { }
    return "coins: needs a whole number from 0 up, like coins:500.";
  }
  if (s.startsWith("xp:")) {
    String[] p = s.split(":");
    boolean good = p.length == 3 && p[1].trim().length() > 0;
    if (good) { try { good = Long.parseLong(p[2].trim()) >= 0L; } catch (Throwable t) { good = false; } }
    if (good) {
      String nm = p[1].trim();
      for (int k = 0; k < nm.length(); k++) { char c = nm.charAt(k); if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))) good = false; }
    }
    if (!good) return "xp: needs a skill name (letters only) and a whole number, like xp:Mining:500.";
    String sk = "," + p[1].trim() + ",";
    if (",Mining,Foraging,Farming,Fishing,Ranching,Orchard,Alchemy,Smithing,Cooking,Exploration,".indexOf(sk) < 0) return "?" + p[1].trim() + " is not a skill SkyySkills grants by default (Mining, Foraging, Farming, Fishing, Ranching, Orchard, Alchemy, Smithing, Cooking) - refused XP stays owed. Save anyway?";   // 0.2.15: + Fishing / Ranching / Orchard
    return null;
  }
  if (s.startsWith("item:")) {          // 0.2.13
    String[] p = s.split(":");
    boolean good = (p.length == 2 || p.length == 3) && p[1].trim().length() > 0;
    if (good && p.length == 3) { try { int n = Integer.parseInt(p[2].trim()); good = n >= 1 && n <= 64; } catch (Throwable t) { good = false; } }
    if (!good) return "item: needs an item id and an amount 1-64, like item:Skyy_Sigil_Unique:1.";
    if (!@PKG@.CollMigrate.ready()) return "?Items are not loaded yet (server still starting), so " + p[1].trim() + " cannot be checked. Save it unchecked?";
    if (!@PKG@.CollRewards.itemLoaded(p[1].trim())) return "?" + p[1].trim() + " is not an item on this server right now - the reward stays owed until it is. Save anyway?";
    return null;
  }
  if (s.startsWith("tierup:")) {          // 0.2.21 C1
    String[] p = s.split(":");
    if (p.length != 3 || p[1].trim().length() == 0 || p[2].trim().length() == 0) return "tierup: needs a tool and a tier, like tierup:pickaxe:Iron.";
    String tw = "," + p[2].trim() + ",";
    if (",Crude,Copper,Iron,Thorium,Cobalt,Adamantite,Mithril,Onyxium,".indexOf(tw) < 0) return "tierup: the tier is Copper, Iron, Thorium, Cobalt, Adamantite, Mithril or Onyxium (like tierup:pickaxe:Iron).";
    if (",pickaxe,hatchet,harvester,can,armor.mining,armor.foraging,armor.farming,armor.fishing,".indexOf("," + p[1].trim().toLowerCase() + ",") < 0) return "?" + p[1].trim() + " is not a tool SkyyGear tiers up today (pickaxe, hatchet, harvester, can, armor.mining, armor.foraging, armor.farming, armor.fishing) - nothing reads it. Save anyway?";
    return null;
  }
  return "Unknown reward " + s + " - use recipe:<id>, coins:<n>, xp:<Skill>:<n>, item:<id>:<n> or tierup:<tool>:<Tier>.";
}""")
# table rewards: key = rewards[<entry>], value = the line's value or null for a removal (always allowed)
M(ckit, r"""
public static String checkReward(String key, String value) {
  if (value == null) return null;
  int a = key.indexOf('[');
  int b = key.lastIndexOf(']');
  if (a < 0 || b <= a) return null;
  String e = key.substring(a + 1, b);
  String form = "An entry is <CollectionId>.<tier>, like Wheat.3.";
  int dot = e.lastIndexOf('.');
  if (dot <= 0 || dot >= e.length() - 1) return form;
  String id = e.substring(0, dot);
  int t = 0;
  try { t = Integer.parseInt(e.substring(dot + 1)); } catch (Throwable x) { return form; }
  int mx = 20;
  String canon = id + "." + t;
  @PKG@.RegData R = @PKG@.CollReg.D;
  if (R != null) {
    Object ci = R.byId.get(id.toLowerCase());
    if (!(ci instanceof Integer)) return "No collection has the id " + id + " (the coll. names in collections.properties, like Wheat or OakLog).";
    int c = ((Integer) ci).intValue();
    mx = @PKG@.CollReg.maxTier(R, c);
    canon = R.id[c] + "." + t;
  }
  if (t < 1 || t > mx) return id + " has tiers 1 to " + mx + ".";
  if (!canon.equals(e)) return "Write it as " + canon + ".";
  int[] n = rewardLines(canon);
  if (n[0] > 1 || n[1] > n[0]) return "rewards.properties has more than one line for " + canon + " - merge them into one line by hand, then Re-read files.";
  String[] toks = @PKG@.CollUtil.csv(value);
  String ask = null;
  for (int i = 0; i < toks.length; i++) {
    if (toks[i].startsWith("item:")) {          // 0.2.13: one item per tier
      for (int j = 0; j < i; j++) if (toks[j].startsWith("item:")) return "One item reward per tier - " + canon + " already gives " + toks[j] + ".";
    }
    String r = rewardToken(toks[i]);
    if (r == null) continue;
    if (!r.startsWith("?")) return r;
    if (ask == null) ask = r;
  }
  return ask;
}""")
# 0.2.3: the read-only Magic Bags rows (custom:, no file key). "Iron Ore I / III / V / VII" when one collection holds all four rarities,
# else "<collection> <tier>" per rarity ("none" = no collection unlocks it). Read from the loaded rewards table (the file as the mod reads it).
M(ckit, r"""
public static String bagLadder(String type) {
  if (@PKG@.CollCat.v2()) return "none - bags now level up in the SkyySacks Pocket Dimension";   // 0.2.9
  @PKG@.RegData R = @PKG@.CollReg.D;
  java.util.HashMap rw = @PKG@.CollReg.REWARDS;
  if (R == null || rw == null) return "(collections are not loaded)";
  String[] sfx = new String[] { "Small", "Medium", "Rare", "Large" };
  String[] cn = new String[4];
  int[] tier = new int[4];
  for (int k = 0; k < 4; k++) {
    String want = "Skyy_Sack_" + type + "_" + sfx[k];
    for (int c = 0; c < R.n; c++) {
      if (R.hidden[c]) continue;
      int mx = @PKG@.CollReg.maxTier(R, c);
      boolean hit = false;
      for (int t = 1; t <= mx && !hit; t++) {
        if (tier[k] > 0 && t >= tier[k]) break;
        String[] tk = (String[]) rw.get(R.id[c].toLowerCase() + "." + t);
        if (tk == null) continue;
        for (int i = 0; i < tk.length && !hit; i++) {
          if (!tk[i].startsWith("recipe:")) continue;
          String rid = tk[i].substring(7).trim();
          int g = rid.indexOf("_Recipe_Generated_");
          if (g > 0 && rid.substring(0, g).equals(want)) { cn[k] = R.name[c]; tier[k] = t; hit = true; }
        }
      }
    }
  }
  boolean one = tier[0] > 0;
  for (int k = 1; k < 4 && one; k++) if (tier[k] <= 0 || !cn[k].equals(cn[0])) one = false;
  if (one) return cn[0] + " " + @PKG@.CollUtil.roman(tier[0]) + " / " + @PKG@.CollUtil.roman(tier[1]) + " / " + @PKG@.CollUtil.roman(tier[2]) + " / " + @PKG@.CollUtil.roman(tier[3]);
  StringBuilder sb = new StringBuilder();
  for (int k = 0; k < 4; k++) {
    if (k > 0) sb.append(", ");
    sb.append(tier[k] > 0 ? cn[k] + " " + @PKG@.CollUtil.roman(tier[k]) : "none");
  }
  return sb.toString();
}""")
