# ================= 0.2.10 fixer: the 10 s flush on a PRIVATE writer (every counts file is fsync'd now - never on the engine's shared scheduler)
# WRITER = one daemon thread "SkyyCollections-writer"; FLUSHQ = a CollFlushJob is queued / running (at most one - a slow disk cannot pile
# them up); FLUSHES = jobs run (the harness counts them). flushSoon: hand the flush to the writer; no writer / refused = inline (0.2.9).
# (WRITER itself is declared before CollStore.save - item 5 below - so saveKeySoon can use it)
F(sto, "public static final java.util.concurrent.atomic.AtomicBoolean FLUSHQ = new java.util.concurrent.atomic.AtomicBoolean(false);")
F(sto, "public static final java.util.concurrent.atomic.AtomicLong FLUSHES = new java.util.concurrent.atomic.AtomicLong();")
cthr.addInterface(pool.get("java.util.concurrent.ThreadFactory"))
C(cthr, "public CollThreads() { }")
M(cthr, r"""
public Thread newThread(Runnable r) {
  Thread t = new Thread(r, "SkyyCollections-writer");
  t.setDaemon(true);
  return t;
}""")
RUN(cfj)
C(cfj, "public CollFlushJob() { }")
M(cfj, r"""
public void run() {
  try {
    @PKG@.CollStore.FLUSHES.incrementAndGet();
    @PKG@.CollStore.flushDirty();
  } catch (Throwable t) { @PKG@.CollUtil.warn("counts flush failed (kept dirty, retried in 10 s): " + t); }
  finally { @PKG@.CollStore.FLUSHQ.set(false); }
}""")
M(sto, r"""
public static void flushSoon() {
  java.util.concurrent.ExecutorService ex = WRITER;
  if (ex != null) {
    if (!FLUSHQ.compareAndSet(false, true)) return;
    try { ex.execute(new @PKG@.CollFlushJob()); return; }
    catch (Throwable t) { FLUSHQ.set(false); }
  }
  flushDirty();
}""")

