# ================= 0.2.13 CollSigMig: the Unique Sigil tokens in a live rewards.properties (once; PROJECT-RULES 4) =================
# Pure text step (ISO-8859-1 chars in and out). null = the 0.2.13 marker is already in a comment line. Else { new text, String[] { entry, old,
# new }* for config-changes.log, String log lines, Integer entries changed, Integer kept by hand, Boolean the loader reads exactly the old
# table + the new tokens }
M(sigm, r"""
public static Object[] update(String text) {
  String[] raw = text.split("\n", -1);
  int n = raw.length;
  String[] l = new String[n];
  for (int i = 0; i < n; i++) l[i] = raw[i].endsWith("\r") ? raw[i].substring(0, raw[i].length() - 1) : raw[i];
  for (int i = 0; i < n; i++) {
    String t = l[i].trim();
    if (t.startsWith("#") && t.indexOf(MARK3.substring(2)) >= 0) return null;
  }
  String cr = text.indexOf("\r\n") >= 0 ? "\r" : "";
  String[] rep = new String[n];
  java.util.ArrayList adds = new java.util.ArrayList();
  java.util.ArrayList rows = new java.util.ArrayList();
  StringBuilder log = new StringBuilder();
  int done = 0;
  int hand = 0;
  int doneMask = 0;
  for (int j = 0; j < K.length; j++) {
    String want = @PKG@.CollCobMig.rkey(K[j] + "=x");
    java.util.ArrayList kl = new java.util.ArrayList();
    for (int i = 0; i < n; i++) { String k = @PKG@.CollCobMig.rkey(l[i]); if (k != null && k.equals(want)) kl.add(Integer.valueOf(i)); }
    boolean has = false;
    for (int q = 0; q < kl.size(); q++) {
      java.util.ArrayList tk = @PKG@.CollCobMig.toks(l[((Integer) kl.get(q)).intValue()]);
      for (int z = 0; z < tk.size(); z++) if (String.valueOf(tk.get(z)).startsWith("item:")) has = true;
    }
    if (has) { log.append("  ").append(K[j]).append(": already has an item reward - left as it is\n"); continue; }
    if (kl.isEmpty()) {
      if (OLDV[j].length() > 0) { hand++; log.append("  ").append(K[j]).append(": no line (an admin removed it) - add ").append(K[j]).append('=').append(TOK).append(" by hand if you like\n"); continue; }
      adds.add(K[j] + "=" + TOK);
      rows.add(K[j]); rows.add("(none)"); rows.add(TOK);
      log.append("  added: ").append(K[j]).append('=').append(TOK).append('\n');
      done++;
      doneMask = doneMask | (1 << j);
      continue;
    }
    int li = ((Integer) kl.get(0)).intValue();
    if (kl.size() != 1 || !@PKG@.CollCobMig.toks(l[li]).equals(@PKG@.CollCobMig.toksOf(OLDV[j]))) {
      hand += kl.size();
      for (int q = 0; q < kl.size(); q++) log.append("  kept hand-edited line ").append(((Integer) kl.get(q)).intValue() + 1).append(": ").append(l[((Integer) kl.get(q)).intValue()].trim()).append(" - append ,").append(TOK).append(" by hand if you like\n");
      continue;
    }
    String cr1 = raw[li].endsWith("\r") ? "\r" : "";
    String ov = @PKG@.CollCobMig.valText(l[li]);
    rep[li] = @PKG@.CollCobMig.rtrim(l[li]) + (ov.length() == 0 ? "" : ",") + TOK + cr1;
    rows.add(@PKG@.CollCobMig.keyText(l[li])); rows.add(ov); rows.add(ov + (ov.length() == 0 ? "" : ",") + TOK);
    log.append("  line ").append(li + 1).append(": ").append(l[li].trim()).append(" + ").append(TOK).append('\n');
    done++;
    doneMask = doneMask | (1 << j);
  }
  java.util.ArrayList out = new java.util.ArrayList();
  int at = -1;
  while (at + 1 < n && l[at + 1].trim().startsWith("#")) at++;
  if (at < 0) out.add(MARK3 + (n > 1 ? (raw[0].endsWith("\r") ? "\r" : "") : cr));
  boolean noEol = n > 0 && raw[n - 1].length() > 0;          // fixer 2: the file has no final newline
  for (int i = 0; i < n; i++) {
    String v = rep[i] != null ? rep[i] : raw[i];
    if (i == n - 1 && noEol && (i == at || !adds.isEmpty()) && !v.endsWith("\r")) v = v + cr;          // fixer 2: a line follows it now - the file's ending
    out.add(v);
    if (i == at) out.add(MARK3 + (raw[i].endsWith("\r") ? "\r" : (i + 1 < n ? "" : (adds.isEmpty() ? "" : cr))));
  }
  if (!adds.isEmpty()) {
    int last = out.size() - 1;
    boolean endsEmpty = last >= 0 && ((String) out.get(last)).length() == 0;
    if (endsEmpty) out.remove(last);
    out.add(cr.length() > 0 ? cr : "");
    out.add(SECTION + cr);
    for (int a = 0; a < adds.size(); a++) out.add((String) adds.get(a) + (endsEmpty || a + 1 < adds.size() ? cr : ""));          // fixer 2: no final newline stays none
    if (endsEmpty) out.add("");
  }
  StringBuilder sb = new StringBuilder(text.length() + 256);
  for (int i = 0; i < out.size(); i++) {
    if (i > 0) sb.append('\n');
    sb.append((String) out.get(i));
  }
  String nt = sb.toString();
  java.util.HashMap want = @PKG@.CollCobMig.table(l);
  for (int j = 0; j < K.length; j++) {
    if ((doneMask & (1 << j)) == 0) continue;
    String k = @PKG@.CollCobMig.rkey(K[j] + "=x");
    java.util.ArrayList c = (java.util.ArrayList) want.get(k);
    if (c == null) { c = new java.util.ArrayList(); want.put(k, c); }
    c.add(TOK);
  }
  String[] nl = nt.split("\n", -1);
  for (int i = 0; i < nl.length; i++) if (nl[i].endsWith("\r")) nl[i] = nl[i].substring(0, nl[i].length() - 1);
  boolean ok = @PKG@.CollCobMig.table(nl).equals(want);
  return new Object[] { nt, (String[]) rows.toArray(new String[0]), log.toString(), Integer.valueOf(done), Integer.valueOf(hand), Boolean.valueOf(ok) };
}""")
