# setup(), after CollSigMig.run and BEFORE CollReg.loadAll: "" = nothing done (no file - the loader writes the 0.2.14 default with the marker -,
# marker already there, or a failure: WARN, the file untouched, retried at the next start); else the INFO line
M(shm, r"""
public static synchronized String run(java.nio.file.Path base) {
  if (base == null) return "";
  java.nio.file.Path f = base.resolve("config.properties");
  try {
    if (!java.nio.file.Files.exists(f, new java.nio.file.LinkOption[0])) return "";
    byte[] old = java.nio.file.Files.readAllBytes(f);
    Object[] r = update(new String(old, "ISO-8859-1"));
    if (r == null) return "";
    byte[] data = ((String) r[0]).getBytes("ISO-8859-1");
    String[] rows = (String[]) r[3];
    if (!@PKG@.CollBypassMig.sameAfter(old, data, rows)) {
      @PKG@.CollUtil.warn("config.properties NOT updated for the 0.2.14 shard credit: the update would change more than the bridge.add.sources line (the file is used as it is; the next start tries again)");
      return "";
    }
    int fi = @PKG@.CollBypassMig.fileIdx();
    if (fi < 0) return "";
    @PKG@.CollBypassMig.mgKit(f.toAbsolutePath().getParent());
    @PKG@.CfgHist.snapshot(fi, old, @PKG@.CfgHist.stamp(), WHO, "before the 0.2.14 shard credit update");
    if (!@PKG@.CollBypassMig.mgSaved(fi, old)) {
      @PKG@.CollUtil.warn("config.properties NOT updated for the 0.2.14 shard credit: the old file could not be kept in " + @PKG@.CfgHist.DIR + " (the file is used as it is; the next start tries again)");
      return "";
    }
    @PKG@.CfgRows.atomicWrite(f, data);
    for (int i = 0; i + 2 < rows.length; i += 3) @PKG@.CfgLog.enqueue(logLine(rows[i], rows[i + 1], rows[i + 2]));
    if (rows.length > 0) @PKG@.CfgLog.flush();
    String chg = (String) r[1];
    String kept = (String) r[2];
    String msg;
    if (chg.length() > 0) msg = "config.properties: SkyyShards Collect may credit collections now: " + chg + " (the old file is in config-history; Server Setup -> Changes can undo it)";
    else if (kept.length() > 0) msg = "config.properties: " + kept + " (0.2.14 shard credit marker added; the old file is in config-history)";
    else msg = "config.properties: bridge.add.sources already lists shard or has no line (the default lists it) - no value changed (0.2.14 marker added; the old file is in config-history)";
    @PKG@.CollUtil.info(msg);
    return msg;
  } catch (Throwable t) {
    @PKG@.CollUtil.warn("could not update config.properties for the 0.2.14 shard credit (the file is used as it is; the next start tries again): " + t);
    return "";
  }
}""")

